import{_ as a,o as e,c as t,a4 as i}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"Windows 11「建议操作」——我用过最反人类的功能","description":"","frontmatter":{"title":"Windows 11「建议操作」——我用过最反人类的功能","date":"2026-07-15T00:00:00.000Z"},"headers":[],"relativePath":"posts/windows11建议操作-最蠢的功能.md","filePath":"posts/windows11建议操作-最蠢的功能.md"}'),o={name:"posts/windows11建议操作-最蠢的功能.md"};function n(r,s,d,l,p,h){return e(),t("div",null,[...s[0]||(s[0]=[i('<h1 id="windows-11「建议操作」——我用过最反人类的功能" tabindex="-1">Windows 11「建议操作」——我用过最反人类的功能 <a class="header-anchor" href="#windows-11「建议操作」——我用过最反人类的功能" aria-label="Permalink to &quot;Windows 11「建议操作」——我用过最反人类的功能&quot;">​</a></h1><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>Windows 11 22H2 加入了「建议操作」(Suggested Actions)。当你复制一个<strong>电话号码、日期、时间、快递单号</strong>时，光标旁边会浮出一个微小的图标，提示你可以「用 Teams 拨打这个号码」或「在日历中添加这个日期」。</p><p>听起来好像很智能，实际体验是灾难级的。</p><h2 id="有多傻逼" tabindex="-1">有多傻逼 <a class="header-anchor" href="#有多傻逼" aria-label="Permalink to &quot;有多傻逼&quot;">​</a></h2><ol><li><p><strong>毫无征兆地卡 UI</strong>。复制内容后按 Alt+Tab 切换窗口，那个小图标卡在渲染队列里，导致界面出现一个残留的<strong>下划线</strong>或<strong>半透明方块</strong>，卡住几秒到十几秒。切一次卡一次。</p></li><li><p><strong>永远用不上</strong>。Windows 在中国——谁用 Teams？谁用系统日历？谁需要 Windows 提醒你「这是一个日期」？我已经是个成年人了，我知道电话号码怎么用。</p></li><li><p><strong>关掉它比打开它难</strong>。这个功能默认开启，关闭入口不在右键菜单里、不在通知栏里、不在任务栏设置里。藏在一级路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>设置 → 系统 → 剪贴板 → 建议操作 → 关</span></span></code></pre></div><p>正常人根本找不到。更离谱的是有些版本这个开关写死了直接不显示，必须改注册表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\SuggestedActions\\Enabled = 0</span></span></code></pre></div></li><li><p><strong>性能开销不配它的存在价值</strong>。一个需要在每次复制操作后实时分析剪贴板文本、识别实体、预计算操作选项、渲染 UI 动画的后台服务。就为了给一个 99% 的人关掉的功能供能。</p></li></ol><h2 id="微软在想什么" tabindex="-1">微软在想什么 <a class="header-anchor" href="#微软在想什么" aria-label="Permalink to &quot;微软在想什么&quot;">​</a></h2><p>「建议操作」是典型的大公司「为了做而做」的功能。产品经理的 OKR 里有一条「提升剪贴板智能化」，于是不管用户要不要，先发了再说。没有人在 Windows 的日常使用场景下，会因为剪贴板多了一个图标而感到生产力提升。只会感到 Windows 又变卡了。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>功能是好功能——如果你是微软内部的 PM 用来写季度总结的话。</p><p>用户的话，关了就行。</p>',11)])])}const _=a(o,[["render",n]]);export{g as __pageData,_ as default};
